import json,pathlib
p=pathlib.Path(__file__).parent
modules=[]
def add(title,level,lesson,example,task,starter,solution,tests,hint,contract):
 modules.append(dict(title=title,level=level,lesson=lesson,example=example,task=task,starter=starter,solution=solution,tests=tests,hint=hint,contract=contract))
add('Values & type inference','Foundations','JavaScript runs your program; TypeScript checks it before it runs. Use string, number and boolean for ordinary values. TypeScript often infers a type from an initial value. An annotation documents a boundary, such as a function parameter. Types are erased at runtime, so they do not validate incoming data.','const schoolName = "North School";\nconst studentCount: number = 120;\nconst isActive: boolean = true;','Implement formatStudent(name, age). Trim the name and return "Name (age)". Give both parameters and the return value explicit types.','function formatStudent(name: string, age: number): string {\n  // Your implementation\n  return "";\n}','function formatStudent(name: string, age: number): string { return `${name.trim()} (${age})`; }',[['Trims surrounding whitespace','formatStudent("  Ana  ", 18) === "Ana (18)"'],['Handles zero','formatStudent("Leo", 0) === "Leo (0)"']], 'Use name.trim() and a template literal.','const check: (name: string, age: number) => string = formatStudent;\n// @ts-expect-error age must be numeric\nformatStudent("Ana", "18");')
add('Functions & optional values','Foundations','Function parameter and return types describe a contract. An optional parameter may be undefined. Use ?? for a fallback only when the value is null or undefined; unlike ||, it preserves an empty string or zero. Default parameters apply when an argument is omitted or undefined.','function welcome(name: string, school?: string): string {\n  return `${name} · ${school ?? "School"}`;\n}','Implement appointmentLabel(student, counselor?). Return "student with counselor". Use "Unassigned" only when counselor is omitted. Preserve an empty counselor string.','function appointmentLabel(student: string, counselor?: string): string {\n  return "";\n}','function appointmentLabel(student: string, counselor?: string): string { return `${student} with ${counselor ?? "Unassigned"}`; }',[['Uses a counselor','appointmentLabel("Ana", "Ms. Cruz") === "Ana with Ms. Cruz"'],['Defaults missing value','appointmentLabel("Ana") === "Ana with Unassigned"'],['Preserves empty string','appointmentLabel("Ana", "") === "Ana with "']], 'Use counselor ?? "Unassigned".','const check: (s: string, c?: string) => string = appointmentLabel;')
add('Objects & interfaces','Foundations','An interface describes the shape of an object. Optional properties use ?. readonly prevents reassignment through that typed reference at compile time; it does not freeze the object at runtime. TypeScript is structurally typed: compatible shapes can be assigned without sharing a class.','interface School {\n  readonly id: string;\n  name: string;\n  logoUrl?: string;\n}','Define Student with readonly id: string, name: string and optional grade: number. Implement studentSummary: "name · Grade n", or "name · Ungraded" when grade is missing.','interface Student {\n  // Define the fields\n}\nfunction studentSummary(student: Student): string {\n  return "";\n}','interface Student { readonly id: string; name: string; grade?: number; }\nfunction studentSummary(student: Student): string { return `${student.name} · ${student.grade === undefined ? "Ungraded" : `Grade ${student.grade}`}`; }',[['Shows grade','studentSummary({id:"1",name:"Ana",grade:11}) === "Ana · Grade 11"'],['Handles no grade','studentSummary({id:"2",name:"Leo"}) === "Leo · Ungraded"'],['Preserves zero','studentSummary({id:"3",name:"Sam",grade:0}) === "Sam · Grade 0"']], 'Check grade === undefined rather than its truthiness.','const s: Student = {id:"1",name:"Ana"};\n// @ts-expect-error id is readonly\ns.id = "2";\n// @ts-expect-error name is required\nconst bad: Student = {id:"1"};')
add('Arrays & immutable updates','Foundations','Use T[] or Array<T> for an array. readonly T[] accepts a read-only array and prevents mutating operations through that parameter. map transforms values; filter selects values. Return a new array when you need an immutable update. This is useful for frontend state.','const names: string[] = ["Ana", "Leo"];\nconst labels = names.map(name => name.toUpperCase());','Implement activeStudentNames. Return names of active students in input order, without changing the input.','interface Learner { name: string; active: boolean; }\nfunction activeStudentNames(students: readonly Learner[]): string[] {\n  return [];\n}','interface Learner { name: string; active: boolean; }\nfunction activeStudentNames(students: readonly Learner[]): string[] { return students.filter(s => s.active).map(s => s.name); }',[['Filters and preserves order','JSON.stringify(activeStudentNames([{name:"Ana",active:true},{name:"Leo",active:false},{name:"Sam",active:true}])) === \'["Ana","Sam"]\''],['Handles empty input','activeStudentNames([]).length === 0'],['Does not mutate','(()=>{const a=Object.freeze([Object.freeze({name:"Ana",active:true})]);return activeStudentNames(a)[0]==="Ana"})()']], 'Combine filter and map.','const check: (s: readonly Learner[]) => string[] = activeStudentNames;')
add('Unions & narrowing','Core TypeScript','A union allows one of several types. Narrow it before accessing type-specific properties. typeof narrows primitives. A discriminated union uses a shared literal property to tell object variants apart. This keeps loading, success and failure states explicit.','type State = { kind: "loading" } | { kind: "ready"; count: number };\nfunction label(s: State) {\n  return s.kind === "ready" ? `${s.count} students` : "Loading";\n}','Implement normalizeId for string | number. Trim strings, and convert numbers to strings.','function normalizeId(id: string | number): string {\n  return "";\n}','function normalizeId(id: string | number): string { return typeof id === "string" ? id.trim() : String(id); }',[['Narrows string','normalizeId("  S-12  ") === "S-12"'],['Converts number','normalizeId(12) === "12"'],['Converts zero','normalizeId(0) === "0"']], 'Check typeof id === "string" before calling trim().','// @ts-expect-error booleans are not IDs\nnormalizeId(true);')
add('Unknown & runtime validation','Core TypeScript','unknown means you must establish what a value is before using it. any disables meaningful checking and can hide mistakes. API responses need runtime validation even when you have TypeScript interfaces. Guard null before inspecting object properties. A type assertion alone does not validate data.','function isText(value: unknown): value is string {\n  return typeof value === "string";\n}','Implement isSchool(value): a type guard for an object with string id and non-empty string name. Reject null, arrays, numbers and blank names.','interface School { id: string; name: string; }\nfunction isSchool(value: unknown): value is School {\n  return false;\n}','interface School { id: string; name: string; }\nfunction isSchool(value: unknown): value is School {\n  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;\n  const v = value as Record<string, unknown>;\n  return typeof v.id === "string" && typeof v.name === "string" && v.name.trim().length > 0;\n}',[['Accepts valid object','isSchool({id:"a",name:"North"})'],['Rejects null','!isSchool(null)'],['Rejects blank name','!isSchool({id:"a",name:" "})'],['Rejects wrong id','!isSchool({id:2,name:"North"})'],['Rejects arrays','!isSchool([])']], 'Narrow object and null first, then inspect its properties.','const check: (v: unknown) => v is School = isSchool;')
add('Generics & reusable functions','Core TypeScript','A generic type parameter preserves the relationship between input and output types. A constraint such as T extends { id: string } states the minimum shape required. This lets you reuse one function without losing the caller’s specific fields. Prefer inference when callers do not need explicit type arguments.','function first<T>(items: readonly T[]): T | undefined {\n  return items[0];\n}','Implement findById<T extends {id: string}>. Return the matching item or undefined. Preserve its original type.','function findById<T extends { id: string }>(items: readonly T[], id: string): T | undefined {\n  return undefined;\n}','function findById<T extends { id: string }>(items: readonly T[], id: string): T | undefined { return items.find(item => item.id === id); }',[['Finds matching item','findById([{id:"1",name:"Ana"},{id:"2",name:"Leo"}],"2")?.name === "Leo"'],['Missing item','findById([{id:"1"}],"x") === undefined'],['Empty collection','findById([],"1") === undefined']], 'Use items.find(). The constraint allows item.id.','const found = findById([{id:"1", score:5}],"1");\nconst score: number | undefined = found?.score;\n// @ts-expect-error id is required\nfindById([{name:"Ana"}],"1");')
add('Utility types & keyof','Core TypeScript','Pick selects properties. Omit removes them. Partial makes properties optional. Readonly prevents assignment through the typed reference. keyof produces a union of property keys. These utilities derive types from a source shape, so changes remain consistent across your app. They do not change runtime values.','interface Profile { id: string; name: string; email: string; }\ntype ProfileUpdate = Partial<Omit<Profile, "id">>;','Implement getField<T, K extends keyof T>(object, key): T[K]. Invalid keys must be rejected by the compiler.','function getField<T, K extends keyof T>(object: T, key: K): T[K] {\n  throw new Error("Implement me");\n}','function getField<T, K extends keyof T>(object: T, key: K): T[K] { return object[key]; }',[['Reads a string','getField({name:"Ana",age:18},"name") === "Ana"'],['Reads a number','getField({name:"Ana",age:18},"age") === 18']], 'Return object[key]. K determines the return type.','const n: number = getField({age:18},"age");\n// @ts-expect-error missing property\ngetField({age:18},"email");')
add('Async functions & API results','Application skills','An async function returns a Promise. await unwraps the fulfilled value; rejected promises still need error handling. Model success and failure explicitly with a discriminated union. fetch does not reject merely because an HTTP response is 404 or 500: check response.ok. Validate untrusted JSON before treating it as your domain type.','type Result<T> = { ok: true; data: T } | { ok: false; error: string };\nasync function example(): Promise<Result<number>> {\n  return { ok: true, data: 3 };\n}','Implement loadName(loader). Await a Promise<string>, trim the value and return a Result<string>. On any rejection return {ok:false,error:"Could not load"}.','type Result<T> = { ok: true; data: T } | { ok: false; error: string };\nasync function loadName(loader: () => Promise<string>): Promise<Result<string>> {\n  return {ok:false,error:"Implement me"};\n}','type Result<T> = { ok: true; data: T } | { ok: false; error: string };\nasync function loadName(loader: () => Promise<string>): Promise<Result<string>> { try { return {ok:true,data:(await loader()).trim()}; } catch { return {ok:false,error:"Could not load"}; } }',[['Awaits and trims','JSON.stringify(await loadName(async()=>" Ana ")) === JSON.stringify({ok:true,data:"Ana"})'],['Handles rejection','JSON.stringify(await loadName(async()=>{throw new Error("offline")})) === JSON.stringify({ok:false,error:"Could not load"})']], 'Use try/catch around await loader().','const check: (l: () => Promise<string>) => Promise<Result<string>> = loadName;')
add('Modules & project boundaries','Application skills','Use export to expose a value or type and import to consume it. import type makes type-only intent explicit. Enable strict in tsconfig.json and run tsc --noEmit for checks. Keep domain types separate from presentation and API parsing. A TypeScript permission check is useful UI logic, but your backend must independently authorize access.','// student.ts\nexport interface Student { id: string; name: string; }\n// elsewhere\n// import type { Student } from "./student";','Implement exported canViewCase(user, caseSchoolId). Permit only a counselor from the same school; reject students, admins and other schools. Export the User interface too. This exercise is a single module.','export interface User { schoolId: string; role: "counselor" | "student" | "admin"; }\nexport function canViewCase(user: User, caseSchoolId: string): boolean {\n  return false;\n}','export interface User { schoolId: string; role: "counselor" | "student" | "admin"; }\nexport function canViewCase(user: User, caseSchoolId: string): boolean { return user.schoolId === caseSchoolId && user.role === "counselor"; }',[['Same school counselor','canViewCase({schoolId:"a",role:"counselor"},"a")'],['Different school blocked','!canViewCase({schoolId:"a",role:"counselor"},"b")'],['Student blocked','!canViewCase({schoolId:"a",role:"student"},"a")'],['Admin blocked','!canViewCase({schoolId:"a",role:"admin"},"a")']], 'Check both school equality and role. Export both declarations.','const check: (u: User, s: string) => boolean = canViewCase;')
add('Final project: appointment service','Final assessment','Combine domain interfaces, literal unions, immutable arrays and explicit result states. Separate validation from updates. Think about edge cases before implementation: incorrect school, duplicate IDs and empty lists. These in-memory checks demonstrate TypeScript skills; a real product also needs backend authorization, database constraints and transaction handling.','type BookingResult = { ok: true; appointments: Appointment[] }\n  | { ok: false; error: "wrong-school" | "duplicate" };','Implement bookAppointment(existing, incoming, schoolId). First reject a mismatched incoming.schoolId with wrong-school. Then reject an existing appointment with the same schoolId and id with duplicate. Otherwise return a new array containing incoming. Never mutate existing.','interface Appointment { id: string; schoolId: string; studentId: string; status: "pending" | "approved"; }\ntype BookingResult = {ok:true;appointments:Appointment[]} | {ok:false;error:"wrong-school"|"duplicate"};\nfunction bookAppointment(existing: readonly Appointment[], incoming: Appointment, schoolId: string): BookingResult {\n  return {ok:false,error:"wrong-school"};\n}','interface Appointment { id: string; schoolId: string; studentId: string; status: "pending" | "approved"; }\ntype BookingResult = {ok:true;appointments:Appointment[]} | {ok:false;error:"wrong-school"|"duplicate"};\nfunction bookAppointment(existing: readonly Appointment[], incoming: Appointment, schoolId: string): BookingResult {\n if(incoming.schoolId !== schoolId) return {ok:false,error:"wrong-school"};\n if(existing.some(a=>a.schoolId===schoolId && a.id===incoming.id)) return {ok:false,error:"duplicate"};\n return {ok:true,appointments:[...existing,incoming]};\n}',[['Adds appointment','(()=>{const a={id:"1",schoolId:"a",studentId:"s",status:"pending"}; const r=bookAppointment([],a,"a");return r.ok && r.appointments.length===1 && r.appointments[0]===a})()'],['Wrong school first','bookAppointment([],{id:"1",schoolId:"b",studentId:"s",status:"pending"},"a").error === "wrong-school"'],['Duplicate rejected','(()=>{const a={id:"1",schoolId:"a",studentId:"s",status:"pending"};return bookAppointment([a],a,"a").error==="duplicate"})()'],['No mutation','(()=>{const old=Object.freeze([]);const a={id:"1",schoolId:"a",studentId:"s",status:"pending"};const r=bookAppointment(old,a,"a");return r.ok && old.length===0 && r.appointments!==old})()'],['Same id in other school allowed','(()=>{const a={id:"1",schoolId:"a",studentId:"s",status:"pending"};const r=bookAppointment([{...a,schoolId:"b"}],a,"a");return r.ok && r.appointments.length===2})()']], 'Use some() for duplicate detection and [...existing, incoming] to create a new array.','const check: (e: readonly Appointment[], a: Appointment, s: string) => BookingResult = bookAppointment;\n// @ts-expect-error status is constrained\nconst bad: Appointment = {id:"1",schoolId:"a",studentId:"s",status:"done"};')
(p/'dist/modules.json').write_text(json.dumps(modules))
